// waitAndHandleCollectionSyncResponse handles the response from a peer.
func (p *P2P) waitAndHandleCollectionSyncResponse(
	ctx context.Context,
	collectionID string,
	collectionName string,
	pubSubRespChan <-chan client.PubsubResponse,
) (cid.Cid, error) {
