		}
	}

	cVersion := C.CString(version)
	cCollectionID := C.CString(collectionID)
	cName := C.CString(name)
	cIdentity := identityFromContext(ctx)
	defer C.free(unsafe.Pointer(cVersion))
	defer C.free(unsafe.Pointer(cCollectionID))
